  private async smart(
    layer: SmartObjectInstanceData,
    registry: ComponentRegistry,
    assets: AssetStore,
    target: HTMLCanvasElement,
    space: RenderSpace,
    world: AffineTransform,
    options: CanvasRenderOptions,
  ) {
    const source = registry.get(layer.componentId).source;
