      return output;
    } catch (error) {
      release(output);
      throw error;
    }
  }

  /** Retire cached pixels without cancelling independently owned reads. */
  retireCache() {
    this.cacheGeneration++;
    this.cache.clear();
    this.identities = new WeakMap();
    if(this.opaque)release(this.opaque);this.opaque=null;
  }

  clear() {
    this.generation++;
    this.retireCache();
  }

  dispose() {
    this.disposed = true;
    this.clear();
  }
}

